  for (let i = 3; i <= Math.sqrt(n); i += 2) {
    if (n % i === 0) return false;
  }
  return true;
}

// Find and print all primes up to N
for (let i = 2; i <= N; i++) {
  if (isPrime(i)) {
    console.log(i);
  }
